import androidx.compose.ui.text.font.FontWeight
import androidx.compose.ui.tooling.preview.Preview
import androidx.compose.ui.unit.dp
import androidx.navigation.NavController
import com.example.flashcard_compose_app.domain.models.Deck
import com.example.flashcard_compose_app.domain.models.RecentDeck
import com.example.flashcard_compose_app.domain.models.User
import com.example.flashcard_compose_app.ui.components.*

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun HomeScreen(navController: NavController) {

    // Dummy data
    val user = User("1", "John Doe", "john@example.com")
    val recentDecks = listOf(
        RecentDeck(Deck("1", "Math Basics"), 1234567890L),
        RecentDeck(Deck("2", "History"), 1234567890L)
    )
    val decks = listOf(
        Deck("1", "Math", children = listOf(Deck("3", "Algebra"), Deck("4", "Geometry"))),
        Deck("2", "Science", children = listOf(Deck("5", "Physics"), Deck("6", "Chemistry")))
    )

    Scaffold(
        modifier = Modifier.fillMaxSize(),

        floatingActionButton = {
            BottomFab(
                onCreateDeckClick = { },
                onCreateFlashcardClick = { }
            )
        }
    ) { homePadding -> // Get padding from Scaffold

    Column(
        modifier = Modifier
            .padding(homePadding)
            .fillMaxSize()
    ) {
            // Welcome Section
            Card(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(16.dp),
                colors = CardDefaults.cardColors(
                    containerColor = MaterialTheme.colorScheme.primary
                ),
                shape = MaterialTheme.shapes.medium
            ) {
                Column(
                    modifier = Modifier.padding(20.dp)
                ) {
                    Text(
                        text = "Welcome, ${user.name}!",
                        style = MaterialTheme.typography.headlineSmall,
                        fontWeight = FontWeight.Bold,
                        color = MaterialTheme.colorScheme.onPrimary
                    )
                    Spacer(modifier = Modifier.height(8.dp))
                    Text(
                        text = "Continue learning with your decks",
                        style = MaterialTheme.typography.bodyMedium,
                        color = MaterialTheme.colorScheme.onPrimary.copy(alpha = 0.87f)
                    )
                }
            }

            // Recently Learned Section
            Text(
                text = "Recently Learned",
                style = MaterialTheme.typography.titleMedium,
                fontWeight = FontWeight.SemiBold,
                modifier = Modifier.padding(horizontal = 16.dp, vertical = 8.dp)
            )

            LazyRow(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(horizontal = 16.dp),
                horizontalArrangement = Arrangement.spacedBy(12.dp)
            ) {
                items(recentDecks) { recent ->
                    Card(
                        modifier = Modifier
                            .width(180.dp)
                            .height(140.dp),
                        colors = CardDefaults.cardColors(
                            containerColor = MaterialTheme.colorScheme.primary
                        ),
                        shape = MaterialTheme.shapes.medium
                    ) {
                        Column(
                            modifier = Modifier
                                .fillMaxSize()
                                .padding(12.dp),
                            verticalArrangement = Arrangement.SpaceBetween
                        ) {
                            Text(
                                recent.deck.name,
                                style = MaterialTheme.typography.titleSmall,
                                fontWeight = FontWeight.Bold,
                                color = MaterialTheme.colorScheme.onPrimary
                            )
                            Text(
                                "Tap to continue",
                                style = MaterialTheme.typography.labelSmall,
                                color = MaterialTheme.colorScheme.onPrimary.copy(alpha = 0.7f)
                            )
                        }
                    }
                }
            }

            Spacer(modifier = Modifier.height(16.dp))

            // All Decks Section
            Text(
                text = "All Decks",
                style = MaterialTheme.typography.titleMedium,
                fontWeight = FontWeight.SemiBold,
                modifier = Modifier.padding(horizontal = 16.dp, vertical = 8.dp)
            )

            // Body
            ExpandableDeckList(decks = decks, onDeckClick = { /* TODO */ })
        }
    }
}


