import com.example.flashcard_compose_app.ui.screens.RegisterScreen

@Composable
fun NavGraph() {
    val context = LocalContext.current
    val authManager = AuthManager(context)
    val startDestination = if (authManager.isLoggedIn()) Screen.Home.route else Screen.Login.route

    val navController = rememberNavController()

    NavHost(
        navController = navController,
        startDestination = startDestination,
        modifier = Modifier.fillMaxSize()
    ) {
        // Auth Screens (Login & Register - Doesn't have MainAppLayout)
        composable(Screen.Login.route) {
            LoginScreen(navController = navController, authManager = authManager)
        }
        composable(Screen.Register.route) {
            RegisterScreen(navController = navController, authManager = authManager)
        }

        // Main App Screens (MainAppLayout)
        composable(Screen.Home.route) {
            MainAppLayout(navController = navController) { innerPadding ->
                HomeScreen(
                    navController = navController,
                    modifier = Modifier.padding(innerPadding)
                )
            }
        }
        composable(Screen.Quiz.route) {
            MainAppLayout(navController = navController) { _ ->
                // QuizScreen
            }
        }
        composable(Screen.Favorites.route) {
            MainAppLayout(navController = navController) { _ ->
                // FavoritesScreen
            }
        }
        composable(Screen.Statistics.route) {
            MainAppLayout(navController = navController) { _ ->
                // StatisticsScreen
            }
        }
        composable(Screen.Settings.route) {
            MainAppLayout(navController = navController) { _ ->
                // SettingsScreen
            }
        }
        composable(Screen.About.route) {
            MainAppLayout(navController = navController) { _ ->
                // AboutScreen
            }
        }
        composable(Screen.Profile.route) {
            MainAppLayout(navController = navController) { _ ->
                // ProfileScreen
            }
        }
    }
}

